    for r in range(n): out[r][c]=8
starts=[0,5,10,15,20]
# fill path cells: color 2 row 1 across 5 cells and column 0 rows 1..3; color 3 column 2 all 5 rows; crossing is 6
for cr,cc,color in [(rr,cc,2) for cc in range(5) for rr in [1]] + [(rr,0,2) for rr in [1,2,3]] + [(rr,2,3) for rr in range(5)]:
    color = 6 if (cr,cc)==(1,2) else color
    for r in range(starts[cr],starts[cr]+4):
        for c in range(starts[cc],starts[cc]+4): out[r][c]=color
